'use strict';
// Construction art of the village: stages of the sites and the stalls of the market rows (village-build.svg, generated by
// scripts/art/village/build.js; reproducibility is checked in scripts/art/village/test_reproducible.py) and how the game
// picks them from the construction state (construction.js siteArt / crewAt / stallStates, app.js syncVillageBuild).
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),path=require('path');
const {pathToFileURL}=require('node:url');
const stat=path.join(__dirname,'../../qw_farm/static');
const app=fs.readFileSync(path.join(stat,'app.js'),'utf8'),css=fs.readFileSync(path.join(stat,'style.css'),'utf8');
const api=fs.readFileSync(path.join(__dirname,'../../qw_farm/api.py'),'utf8');
const sprite=fs.readFileSync(path.join(stat,'village-build.svg'),'utf8');
const load=()=>import(pathToFileURL(path.join(stat,'construction.js')).href);
const appConst=name=>{const s=app.slice(app.indexOf(`const ${name}=`));return JSON.parse(s.slice(s.indexOf('=')+1,s.indexOf(';\n')));};

test('sprite: every stage of every site and both views of every stall, vector and CSP-safe',()=>{
 const ids=new Set([...sprite.matchAll(/<symbol id="([^"]+)" viewBox="([^"]+)"/g)].map(m=>m[1]));
 for(const site of ['stalls','tavern','greenhouse','fairground'])for(const st of ['soon','pit','frame','done'])assert.ok(ids.has(`site-${site}-${st}`),`site-${site}-${st}`);
 for(const site of ['tavern','greenhouse','fairground'])assert.ok(ids.has(`site-${site}-done-night`),'lit windows of the finished building');
 for(const stall of ['magpie','igor','sonya','agata','post','player'])for(const v of ['closed','open','open-night'])assert.ok(ids.has(`stall-${stall}-${v}`),`stall-${stall}-${v}`);
 assert.doesNotMatch(sprite,/<image|data:|<style|style=|<script|href=/i,'no raster, inline style, script or links');
 assert.ok(sprite.length<200000,'stays light');
});
test('app.js places each piece by the box its symbol is drawn in',()=>{
 const build=appConst('VILLAGE_BUILD');
 const boxes=Object.fromEntries([...sprite.matchAll(/<symbol id="([^"]+)" viewBox="([^"]+)"/g)].map(m=>[m[1],m[2].split(' ').map(Number)]));
 for(const [id,box] of Object.entries(build.boxes))assert.deepEqual(box,boxes[id],id);
 assert.deepEqual(build.sites,['stalls','tavern','greenhouse','fairground']);
 assert.deepEqual(build.stalls,['magpie','igor','sonya','agata','post','player']);
 for(const id of build.sites)assert.equal(build.crew[id].length,3,'Krot and two residents');
 assert.match(app,/const VILLAGE_CREW=\{krot:'<svg[^']*bc-plan[^']*',pooh:'<svg[^']*bc-hammer[^']*',kaya:'<svg[^']*bc-shovel[^']*'\}/);
});
test('construction.js: the stage art follows the finished works, the crew stands only while the residents work',async()=>{
 const C=await load();
 assert.equal(C.siteArt(null),'soon');assert.equal(C.siteArt({status:'soon'}),'soon');
 assert.equal(C.siteArt({status:'collecting',stage:0}),'soon');assert.equal(C.siteArt({status:'working',stage:0}),'pit');
 assert.equal(C.siteArt({status:'collecting',stage:1}),'pit');assert.equal(C.siteArt({status:'working',stage:1}),'frame');
 assert.equal(C.siteArt({status:'collecting',stage:2}),'frame');assert.equal(C.siteArt({status:'working',stage:2}),'frame');
 assert.equal(C.siteArt({status:'done',stage:2}),'done');
 assert.equal(C.crewAt({status:'working'}),true);assert.equal(C.crewAt({status:'collecting'}),false);assert.equal(C.crewAt(null),false);
});
test('construction.js: Сорока opens on her visit, Sonya shutters 23–7 Moscow, the players\' stall opens with lots',async()=>{
 const C=await load(),noon=Date.UTC(2026,9,23,9)/1000,night=Date.UTC(2026,9,23,21)/1000;   // 12:00 and 00:00 in Moscow
 assert.deepEqual(C.stallStates({},noon),{magpie:'closed',igor:'open',sonya:'open',agata:'open',post:'open',player:'closed'});
 const me={merchant_view:{active:true},village_build:{rows:{lots:[{id:1}],own:[]}}};
 assert.deepEqual(C.stallStates(me,night),{magpie:'open',igor:'open',sonya:'closed',agata:'open',post:'open',player:'open'});
});
test('app.js: layers under and above the night tint, the crew, synced with the village scene; CSS keeps the motion optional',()=>{
 assert.match(app,/villageFestLayer\('base'\),villageBuildLayer\('base'\),sun,villageFx\(\),night,villageFestLayer\('glow'\),villageBuildLayer\('glow'\),/);
 assert.match(app,/villageWaterWheel\(\),villageCrewLayer\(\),actors,/);
 assert.match(app,/syncVillageSites\(\);syncVillageBuild\(\);/);
 assert.match(app,/u\.setAttribute\('href',`\/app\/farm\/assets\/\$\{VILLAGE_BUILD\.asset\}#\$\{id\}`\)/);
 assert.match(css,/:root:not\(\[data-farm-theme=night\]\) \.village-build-glow\{display:none\}/);
 assert.match(css,/@media\(prefers-reduced-motion:no-preference\)\{\n \.village-crew \.bc-plan\{animation/);
});
test('api.py serves village-build.svg',{todo:'add village-build.svg to qw_farm/api.py ASSETS (qw_farm/*.py was held by another task)'},()=>{
 assert.match(api,/'village-build\.svg'/);
});
